
begin;
create table sim_murid_private.digital_books(id uuid primary key default gen_random_uuid(),title text not null check(length(btrim(title)) between 1 and 300),author text not null default '',publisher text not null default '',publication_year integer check(publication_year between 1800 and 2200),version text not null default '',category text not null default '',subject_id uuid references public.subjects(id),level integer check(level between 7 and 9),external_url text check(external_url is null or external_url~'^https://[^[:space:]]+$'),premium boolean not null default false,active boolean not null default true,created_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());
create index book_subject on sim_murid_private.digital_books(subject_id);
create function public.app_book_allowed(p_actor uuid,p_session uuid,p_id uuid) returns boolean language sql stable security invoker set search_path='' as $$select public.app_onboarding_ready(p_actor,p_session) and exists(select 1 from sim_murid_private.digital_books b where b.id=p_id and b.active and (not b.premium or public.app_education_admin(p_actor,p_session) or exists(select 1 from public.user_access_flags where user_id=p_actor and premium_access)))$$;
create function public.app_asset_get(p_actor uuid,p_session uuid,p_id uuid,p_download boolean default false) returns jsonb language sql stable security invoker set search_path='' as $$select to_jsonb(a) from sim_murid_private.learning_assets a where a.id=p_id and a.state='ready' and (public.app_education_admin(p_actor,p_session) or(case a.kind when 'book' then public.app_book_allowed(p_actor,p_session,a.target_id) when 'diploma' then public.app_diploma_allowed(p_actor,p_session,a.target_id,p_download) else false end))$$;
create function public.app_asset_write(p_actor uuid,p_session uuid,p_action text,p_data jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare target uuid;asset sim_murid_private.learning_assets%rowtype;begin
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;target=(p_data->>'id')::uuid;
 perform 1 from sim_murid_private.operations_state for update;
 if p_action='prepare' then
 if (p_data->>'kind'='book' and not exists(select 1 from sim_murid_private.digital_books where id=(p_data->>'targetId')::uuid and active)) or(p_data->>'kind'='diploma' and not public.app_ops_role((p_data->>'targetId')::uuid,'alumni')) then return jsonb_build_object('code','invalid');end if;
 insert into sim_murid_private.learning_assets(id,kind,target_id,slot,replaces_id,path,mime,size,filename,created_by) values(target,p_data->>'kind',(p_data->>'targetId')::uuid,coalesce(p_data->>'slot',case when p_data->>'kind'='book' then 'PDF' else 'IJAZAH' end),(select id from sim_murid_private.learning_assets where kind=p_data->>'kind' and target_id=(p_data->>'targetId')::uuid and slot=coalesce(p_data->>'slot',case when p_data->>'kind'='book' then 'PDF' else 'IJAZAH' end) and state='ready'),(p_data->>'kind')||'/'||(p_data->>'targetId')||'/'||target::text,p_data->>'mime',(p_data->>'size')::bigint,p_data->>'filename',p_actor);
 elsif p_action in('ready','failed') then
 select * into asset from sim_murid_private.learning_assets where id=target and state='pending' and created_at>now()-interval '2 hours';if not found then return jsonb_build_object('code','invalid');end if;
 if p_action='ready' then
 if asset.replaces_id is distinct from (select id from sim_murid_private.learning_assets where kind=asset.kind and target_id=asset.target_id and slot=asset.slot and state='ready') then return jsonb_build_object('code','stale');end if;
 if p_data->>'sha256'!~'^[a-f0-9]{64}$' then return jsonb_build_object('code','invalid');end if;
 update sim_murid_private.learning_assets set state='deleted' where kind=asset.kind and target_id=asset.target_id and slot=asset.slot and state='ready';
 end if;
 update sim_murid_private.learning_assets set state=case when p_action='ready' then 'ready' else 'failed' end,sha256=p_data->>'sha256' where id=target;
 elsif p_action='purge' then update sim_murid_private.learning_assets set state='purged' where id=target and (state in('failed','deleted') or(state='pending' and created_at<now()-interval '2 hours'));
 elsif p_action='delete' then update sim_murid_private.learning_assets set state='deleted' where id=target;
 else return jsonb_build_object('code','invalid');end if;return jsonb_build_object('code','saved','id',target);end$$;

create function public.app_asset_admin(p_actor uuid,p_session uuid,p_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$select to_jsonb(a) from sim_murid_private.learning_assets a where a.id=p_id and public.app_education_admin(p_actor,p_session)$$;
create function public.app_asset_cleanup(p_actor uuid,p_session uuid) returns jsonb language sql stable security invoker set search_path='' as $$select case when public.app_education_admin(p_actor,p_session) then (select coalesce(jsonb_agg(jsonb_build_object('id',id,'path',path)),'[]') from (select id,path from sim_murid_private.learning_assets where state in('deleted','failed') or(state='pending' and created_at<now()-interval '2 hours') order by created_at limit 20)x) end$$;
create function public.app_learning_write(p_actor uuid,p_session uuid,p_request uuid,p_revision bigint,p_module text,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare old sim_murid_private.operations_requests%rowtype;v bigint;r jsonb;target uuid;snap jsonb;item jsonb;cls uuid;sub uuid;before_image jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module in('books','promotions') and not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if p_module='grades' then cls=(p_command->>'classId')::uuid;sub=(p_command->>'subjectId')::uuid;if p_command->>'id' is not null then select class_id,subject_id into cls,sub from sim_murid_private.assessments where id=(p_command->>'id')::uuid;end if;if not public.app_teaching_access(p_actor,p_session,cls,sub,true) then return jsonb_build_object('code','denied');end if;end if;
 if p_module='reports' and not(public.app_education_admin(p_actor,p_session) or exists(select 1 from public.classes where id=(p_command->>'classId')::uuid and homeroom_teacher_id=p_actor)) then return jsonb_build_object('code','denied');end if;
 select revision into v from sim_murid_private.operations_state for update;
 select * into old from sim_murid_private.operations_requests where id=p_request;if found then if old.actor=p_actor and old.module='learning:'||p_module and old.command=p_command then return old.result;end if;return jsonb_build_object('code','request_conflict');end if;
 if v is distinct from p_revision then return jsonb_build_object('code','stale');end if;
 if p_module='grades' and p_command->>'id' is null and p_command->>'type'='batch' and p_command->>'kind'<>'PH' then select id into target from sim_murid_private.assessments where class_id=cls and subject_id=sub and semester=case when extract(month from (p_command->>'date')::date)>=7 then 1 else 2 end and kind=p_command->>'kind' and voided_at is null;else target=(p_command->>'id')::uuid;end if;
 if p_module='grades' and target is not null then select to_jsonb(a)||jsonb_build_object('scores',(select jsonb_agg(sc) from sim_murid_private.assessment_scores sc where sc.assessment_id=a.id)) into before_image from sim_murid_private.assessments a where a.id=target;end if;
 if p_module='grades' then r=public.app_grades_mutate(p_actor,p_session,p_command);
 elsif p_module='promotions' then r=public.app_promotions_mutate(p_actor,p_session,p_command);
 elsif p_module='reports' and p_command->>'type'='publish' then
 cls=(p_command->>'classId')::uuid;
 if not(public.app_education_admin(p_actor,p_session) or exists(select 1 from public.classes where id=cls and homeroom_teacher_id=p_actor)) then return jsonb_build_object('code','denied');end if;
 if jsonb_array_length(p_command->'studentIds') not between 1 and 500 then return jsonb_build_object('code','invalid');end if;
 for item in select value from jsonb_array_elements(p_command->'studentIds') loop
 snap=public.app_report_draft(p_actor,p_session,(item#>>'{}')::uuid,cls,(p_command->>'semester')::integer);
 if snap is null or jsonb_array_length(snap->'subjects')=0 or exists(select 1 from jsonb_array_elements(snap->'subjects')x where x->>'complete'<>'true') then return jsonb_build_object('code','incomplete');end if;
 if exists(select 1 from sim_murid_private.report_snapshots where student_id=(item#>>'{}')::uuid and class_id=cls and semester=(p_command->>'semester')::integer) then return jsonb_build_object('code','published');end if;
 end loop;
 for item in select value from jsonb_array_elements(p_command->'studentIds') loop
 snap=public.app_report_draft(p_actor,p_session,(item#>>'{}')::uuid,cls,(p_command->>'semester')::integer);
 insert into sim_murid_private.report_snapshots(student_id,class_id,academic_year_id,semester,snapshot,published_by) select (item#>>'{}')::uuid,cls,academic_year_id,(p_command->>'semester')::integer,jsonb_set(snap,'{draft}','false'),p_actor from public.classes where id=cls returning id into target;end loop;r=jsonb_build_object('code','saved','id',target);
 elsif p_module='books' then
 if not public.app_education_admin(p_actor,p_session) then return jsonb_build_object('code','denied');end if;target=(p_command->>'id')::uuid;
 if target is not null and not exists(select 1 from sim_murid_private.digital_books where id=target) then return jsonb_build_object('code','not_found');end if;
 if p_command->>'type'='void' then update sim_murid_private.digital_books set active=false,updated_at=now() where id=target;r=jsonb_build_object('code','saved','id',target);
 elsif p_command->>'type'='book' then
 if target is null then insert into sim_murid_private.digital_books(title,author,publisher,publication_year,version,category,subject_id,level,external_url,premium,created_by) values(p_command->>'title',coalesce(p_command->>'author',''),coalesce(p_command->>'publisher',''),(p_command->>'year')::integer,coalesce(p_command->>'version',''),coalesce(p_command->>'category',''),(p_command->>'subjectId')::uuid,(p_command->>'level')::integer,nullif(p_command->>'url',''),(p_command->>'premium')::boolean,p_actor) returning id into target;
 else update sim_murid_private.digital_books set title=p_command->>'title',author=coalesce(p_command->>'author',''),publisher=coalesce(p_command->>'publisher',''),publication_year=(p_command->>'year')::integer,version=coalesce(p_command->>'version',''),category=coalesce(p_command->>'category',''),subject_id=(p_command->>'subjectId')::uuid,level=(p_command->>'level')::integer,external_url=nullif(p_command->>'url',''),premium=(p_command->>'premium')::boolean,updated_at=now() where id=target;end if;r=jsonb_build_object('code','saved','id',target);
 else return jsonb_build_object('code','invalid');end if;
 else return jsonb_build_object('code','invalid');end if;
 if r->>'code'='saved' then update sim_murid_private.operations_state set revision=revision+1;
 insert into sim_murid_private.operations_requests(id,actor,module,command,result) values(p_request,p_actor,'learning:'||p_module,p_command,r);
 insert into sim_murid_private.activity_logs(actor_id,actor_kind,action,entity_type,entity_id,request_id,metadata) values(p_actor,'user',p_module||'.'||(p_command->>'type'),p_module,(r->>'id')::uuid,p_request,jsonb_build_object('command',p_command,'before',before_image));end if;return r;
exception when unique_violation then return jsonb_build_object('code','duplicate');when invalid_text_representation or check_violation or not_null_violation or foreign_key_violation or datetime_field_overflow or numeric_value_out_of_range then return jsonb_build_object('code','invalid');end$$;
create function public.app_learning_read(p_actor uuid,p_session uuid,p_module text,p_filters jsonb default '{}') returns jsonb language plpgsql stable security invoker set search_path='' as $$declare cls uuid;sub uuid;student uuid;sem integer;yr uuid;result jsonb:='[]';extra jsonb:='{}';people jsonb:='[]';classes jsonb;admin boolean;canwrite boolean;total integer;pg integer;begin
 if not public.app_onboarding_ready(p_actor,p_session) or p_module not in('grades','reports','promotions','books') then return null;end if;
 admin=public.app_education_admin(p_actor,p_session);cls=(p_filters->>'classId')::uuid;sub=(p_filters->>'subjectId')::uuid;student=(p_filters->>'studentId')::uuid;sem=coalesce((p_filters->>'semester')::integer,case when extract(month from public.app_ops_today())>=7 then 1 else 2 end);
 if sem not in(1,2) then return null;end if;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('year',y.start_year) order by y.start_year desc,c.level,c.name),'[]') into classes from public.classes c join public.academic_years y on y.id=c.academic_year_id where admin or public.app_education_task(p_actor,'school_head') or c.homeroom_teacher_id=p_actor or exists(select 1 from sim_murid_private.lesson_schedules l where l.class_id=c.id and l.teacher_id=p_actor and l.archived_at is null) or exists(select 1 from sim_murid_private.enrollments e where e.class_id=c.id and public.app_ops_student(p_actor,p_session,e.student_id));
 if cls is not null and not exists(select 1 from jsonb_array_elements(classes)x where (x->>'id')::uuid=cls) then return null;end if;
 select academic_year_id into yr from public.classes where id=cls;
 select coalesce(jsonb_agg(q order by q.full_name),'[]') into people from(select distinct p.id,p.username,p.full_name,r.role_code,e.class_id from public.profiles p join public.user_roles r on r.user_id=p.id left join sim_murid_private.enrollments e on e.student_id=p.id and (case when p_module='promotions' then e.ended_at is null else true end) where r.role_code in('student','applicant','alumni') and (cls is null or e.class_id=cls) and (student is null or p.id=student) and (admin or public.app_ops_student(p_actor,p_session,p.id) or (e.class_id is not null and (exists(select 1 from public.classes where id=e.class_id and homeroom_teacher_id=p_actor) or exists(select 1 from sim_murid_private.lesson_schedules where class_id=e.class_id and teacher_id=p_actor and archived_at is null)))) limit 2000)q;
 canwrite=case p_module when 'grades' then public.app_teaching_access(p_actor,p_session,cls,sub,true) else admin end;
 extra=jsonb_build_object('years',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'start_year',start_year) order by start_year desc),'[]') from public.academic_years),'subjects',(select coalesce(jsonb_agg(jsonb_build_object('id',sb.id,'name',sb.name) order by sort_order),'[]') from public.subjects sb where sb.active and (p_module<>'grades' or cls is null or admin or public.app_teaching_access(p_actor,p_session,cls,sb.id,false))));
 if p_module='grades' then
 select coalesce(jsonb_agg(to_jsonb(a)||jsonb_build_object('subject_name',sb.name,'scores',(select coalesce(jsonb_agg(jsonb_build_object('student_id',sc.student_id,'name',p.full_name,'value',sc.value,'notes',sc.notes)),'[]') from sim_murid_private.assessment_scores sc join public.profiles p on p.id=sc.student_id where sc.assessment_id=a.id and (public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,false) or public.app_ops_student(p_actor,p_session,sc.student_id))),'can_edit',public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,true) and (a.teacher_id=p_actor or admin)) order by a.assessment_date desc,a.ph_number desc),'[]') into result from sim_murid_private.assessments a join public.subjects sb on sb.id=a.subject_id where a.voided_at is null and (cls is null or a.class_id=cls) and (sub is null or a.subject_id=sub) and a.semester=sem and (public.app_teaching_access(p_actor,p_session,a.class_id,a.subject_id,false) or exists(select 1 from sim_murid_private.assessment_scores sc where sc.assessment_id=a.id and public.app_ops_student(p_actor,p_session,sc.student_id)));
 extra=extra||jsonb_build_object('kkm',case when cls is not null and sub is not null then (select value from sim_murid_private.minimum_grades where class_id=cls and subject_id=sub and academic_year_id=yr and semester=sem) end);
 elsif p_module='reports' and cls is not null then
 select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','draft',public.app_report_draft(p_actor,p_session,(p->>'id')::uuid,cls,sem),'published',(select jsonb_build_object('id',s.id,'snapshot',jsonb_set(s.snapshot,'{subjects}',coalesce((select jsonb_agg(v) from jsonb_array_elements(s.snapshot->'subjects')v where public.app_ops_student(p_actor,p_session,s.student_id) or exists(select 1 from public.classes where id=s.class_id and homeroom_teacher_id=p_actor) or public.app_teaching_access(p_actor,p_session,s.class_id,(v->>'subject_id')::uuid,false)),'[]')),'published_at',s.published_at) from sim_murid_private.report_snapshots s where s.student_id=(p->>'id')::uuid and s.class_id=cls and s.semester=sem))),'[]') into result from jsonb_array_elements(people)p;
 elsif p_module='promotions' then
 extra=extra||jsonb_build_object('access',(select to_jsonb(s) from sim_murid_private.diploma_settings s));
 select coalesce(jsonb_agg(jsonb_build_object('student_id',p->>'id','name',p->>'full_name','role',p->>'role_code','class_id',p->>'class_id','diploma',case when admin or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false) or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true) then (select to_jsonb(d) from sim_murid_private.diplomas d where d.user_id=(p->>'id')::uuid) end,'canView',public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false),'canDownload',public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true),'assets',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'filename',a.filename,'mime',a.mime,'slot',a.slot)),'[]') from sim_murid_private.learning_assets a where a.kind='diploma' and a.target_id=(p->>'id')::uuid and a.state='ready' and (admin or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,false) or public.app_diploma_allowed(p_actor,p_session,(p->>'id')::uuid,true))))),'[]') into result from jsonb_array_elements(people)p;
 elsif p_module='books' then
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('assets',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'filename',filename)),'[]') from sim_murid_private.learning_assets where kind='book' and target_id=b.id and state='ready')) order by b.title),'[]') into result from sim_murid_private.digital_books b where (admin or public.app_book_allowed(p_actor,p_session,b.id)) and b.active and (coalesce(p_filters->>'query','')='' or b.title ilike '%'||(p_filters->>'query')||'%' or b.author ilike '%'||(p_filters->>'query')||'%') and (sub is null or b.subject_id=sub) and (p_filters->>'level' is null or b.level=(p_filters->>'level')::integer) and (p_filters->>'category' is null or b.category=p_filters->>'category');people='[]';
 end if;
 total=jsonb_array_length(result);pg=greatest(1,coalesce((p_filters->>'page')::integer,1));
 if p_module='books' then result=coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(result)with ordinality as x(value,ord) where ord>(pg-1)*50 and ord<=pg*50),'[]');end if;extra=extra||jsonb_build_object('total',total,'page',pg,'canPublish',admin or exists(select 1 from public.classes where id=cls and homeroom_teacher_id=p_actor));
 return jsonb_build_object('module',p_module,'revision',(select revision from sim_murid_private.operations_state),'today',public.app_ops_today(),'isAdmin',admin,'canWrite',canwrite,'classes',classes,'people',people,'semester',sem,'rows',result,'extra',extra);end$$;
do $$declare t text;r record;begin
 foreach t in array array['fee_brackets','withdrawal_sequences','withdrawal_slips','slip_deliveries','grade_counters','minimum_grades','assessments','assessment_scores','report_snapshots','promotion_history','diploma_settings','diplomas','learning_assets','digital_books'] loop
 execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on sim_murid_private.%I to service_role',t);end loop;
 for r in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'app_learning_%' or p.proname like 'app_asset_%' or p.proname like 'app_slip_%' or p.proname in('app_fee_quote','app_savings_mutate','app_savings_mutate_v20','app_operations_read','app_operations_read_v20','app_teaching_access','app_grades_mutate','app_report_draft','app_diploma_allowed','app_promotions_mutate','app_book_allowed')) loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;
end$$;
-- Dedicated private bucket, no client Storage policies.
do $$begin if to_regclass('storage.buckets') is not null then execute $q$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('learning-private','learning-private',false,52428800,array['application/pdf','image/png','image/jpeg']) on conflict(id) do nothing$q$;end if;end$$;
create index fee_brackets_updated_by_lookup on sim_murid_private.fee_brackets(updated_by);
create index slip_deliveries_recipient_id_lookup on sim_murid_private.slip_deliveries(recipient_id);
create index grade_counters_class_id_lookup on sim_murid_private.grade_counters(class_id);
create index grade_counters_subject_id_lookup on sim_murid_private.grade_counters(subject_id);
create index minimum_grades_subject_id_lookup on sim_murid_private.minimum_grades(subject_id);
create index minimum_grades_academic_year_id_lookup on sim_murid_private.minimum_grades(academic_year_id);
create index minimum_grades_updated_by_lookup on sim_murid_private.minimum_grades(updated_by);
create index assessments_subject_id_lookup on sim_murid_private.assessments(subject_id);
create index assessments_academic_year_id_lookup on sim_murid_private.assessments(academic_year_id);
create index report_snapshots_class_id_lookup on sim_murid_private.report_snapshots(class_id);
create index report_snapshots_academic_year_id_lookup on sim_murid_private.report_snapshots(academic_year_id);
create index report_snapshots_published_by_lookup on sim_murid_private.report_snapshots(published_by);
create index promotion_history_source_year_id_lookup on sim_murid_private.promotion_history(source_year_id);
create index promotion_history_target_year_id_lookup on sim_murid_private.promotion_history(target_year_id);
create index promotion_history_from_class_id_lookup on sim_murid_private.promotion_history(from_class_id);
create index promotion_history_to_class_id_lookup on sim_murid_private.promotion_history(to_class_id);
create index promotion_history_processed_by_lookup on sim_murid_private.promotion_history(processed_by);
create index diplomas_updated_by_lookup on sim_murid_private.diplomas(updated_by);
create index learning_assets_replaces_id_lookup on sim_murid_private.learning_assets(replaces_id);
create index learning_assets_created_by_lookup on sim_murid_private.learning_assets(created_by);
create index digital_books_created_by_lookup on sim_murid_private.digital_books(created_by);
create index student_duty_class_year_lookup on sim_murid_private.student_duty_assignments(class_id,academic_year_id);
commit;
